contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: caller provides an amount to deposit (sent to this test), then forwards it into c via fallback,
    // then attempts withdrawAll; assert that withdrawAll cannot reduce c's balance when called by a non-owner.
    function runTest(uint depositAmount) public payable {
        // Precondition: this contract must hold at least depositAmount so it can send to c
        require(msg.value == depositAmount, "send exact depositAmount as msg.value");
        require(depositAmount > 0, "deposit must be positive");

        // Send Ether into c so its balance increases and depositsCount increments (via fallback)
        (bool s, ) = address(c).call{value: depositAmount}("");
        require(s, "funding c failed");

        // Record c balance before withdrawAll attempt
        uint before = address(c).balance;

        // Attempt to call withdrawAll as this (non-owner) caller
        // This is the deciding call: in P it will revert (only owner), in M it will succeed and drain funds
        // We capture whether it reverts by using a low-level call
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        uint after = address(c).balance;

        // Rule: if caller is not owner then withdrawAll must not decrease c's balance.
        // We cannot read owner directly (but owner is public), so we express the rule using the recorded call success:
        // If the low-level call succeeded then the caller must be the owner; equivalently, if caller is not owner the call must fail and balance unchanged.
        // We assert that either withdrawAll failed, or it did not change the balance.
        assert(success == false || after >= before);
    }

    // allow this contract to receive ETH for forwarding into c
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // no special precondition needed
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // On the original contract P this must always revert for non-owner callers.
        // The general rule: withdrawAll does not succeed when called by an address that is not the contract's owner.
        // We cannot read owner directly here, so we assert that either the call reverted or msg.sender equals c.owner().
        // Note: c.owner() is a public getter available on C.
        address owner = c.owner();
        assert(reverted || msg.sender == owner);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
