    function run() public payable {
        // require caller is not the owner of c
        require(msg.sender != c.owner());
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // For the original contract, non-owners must get a revert.
        assert(reverted == true);
    }
    receive() external payable { }
}

