pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters:
    // - uint256 value: amount of wei forwarded to sendMoney
    // - address caller: the external caller that will invoke sendMoney
    // We must deploy an adversarial callee that will ACCEPT funds but do nothing (succeed)
    // and another that will REVERT on call to simulate a failing external call.

    function testFuzz_property(uint256 value, address caller, bool makeCalleeRevert) public {
        // keep fuzzed values in wide but sensible bounds
        vm.assume(caller != address(0));
        // fund the caller so it can send value
        uint256 fundAmount = bound(value, 0, 1 ether);
        vm.deal(caller, fundAmount);

        // deploy helper callee depending on the flag
        address calleeAddr;
        if (makeCalleeRevert) {
            Reverter r = new Reverter();
            calleeAddr = address(r);
        } else {
            Responder r = new Responder();
            calleeAddr = address(r);
        }

        // deposit some ether into C by directly sending to fallback (any address can send)
        // make sure C has some balance so withdrawAll would matter
        uint256 initialFund = 0.5 ether;
        vm.deal(address(this), initialFund);
        // send to c's fallback
        (bool sent,) = address(c).call{value: initialFund}("");
        require(sent);

        // record balance before sendMoney
        uint256 before = address(c).balance;

        // craft arbitrary calldata (empty here) and call sendMoney as `caller`
        bytes memory data = "";
        vm.prank(caller);
        // forward up to fundAmount or requested value
        c.sendMoney{value: bound(value, 0, fundAmount)}(calleeAddr, bound(value, 0, fundAmount), data);

        // After sendMoney completes, in the reference contract only the owner can withdraw.
        // Therefore the contract balance should NOT be lower due to a non-owner being able to call withdrawAll
        // (i.e., for all inputs, the reference ensures that a call to sendMoney does not change address(c).balance
        // via unauthorized withdrawal). We assert that address(c).balance == before.
        // This is the single assertion required.
        assertTrue(address(c).balance == before);
    }
}

// adversarial helper that reverts on any call
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
}

// benign helper that accepts funds
contract Responder {
    receive() external payable {}
    fallback() external payable {}
}

