pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters:
    // - depositor: an address that will fund the contract (can be owner or not)
    // - calleeIsReverter: whether we call a callee that reverts (0 or 1 used as boolean)
    // - sendValue: value sent via sendMoney
    function testFuzz_property(address depositor, uint256 sendValue, uint256 calleeIsReverter) public {
        // keep domains sensible but wide
        vm.assume(depositor != address(0));
        // cap value to a reasonable bound for vm.deal
        uint256 value = bound(sendValue, 0, 1 ether);

        // fund depositor so it can send ETH into c via sendMoney
        vm.deal(depositor, 2 ether);

        // deploy adversarial callee that can revert or accept funds depending on flag
        Reverter rev = new Reverter();
        Accepting acc = new Accepting();

        address callee = (calleeIsReverter % 2 == 1) ? address(rev) : address(acc);

        // depositor sends ETH to contract c via a low-level call routed through c.sendMoney
        // only the owner can call sendMoney in the reference; set sender to the contract owner (setUp deployer)
        // setUp deployer is address(this) in tests, which is owner
        // make sure c has some balance to be withdrawable
        // Owner will send some initial funds into c by directly calling sendMoney to self-callee (no-op) via payable fallback

        // Top up c by calling its fallback via a direct plain transfer from depositor
        vm.prank(depositor);
        (bool okDeposit,) = payable(address(c)).call{value: value}("0x");
        // deposit via fallback increments depositsCount and increases contract balance on both reference and mutant
        // require deposit success for admissible scenario
        vm.assume(okDeposit);

        // Record balance before the adversarial interaction
        uint256 before = address(c).balance;

        // Owner uses sendMoney to ask c to forward `value` to `callee` with empty data
        // sendMoney is protected by onlyOwner in reference so only owner (this) can call it; set the sender to owner
        vm.prank(address(this));
        // sendMoney is not declared payable in interface but uses low-level call with value param; call without value passes 0
        c.sendMoney(callee, value, "");

        // After sendMoney returns, in the reference: onlyOwner prevents non-owners from withdrawing, so address(c).balance is either unchanged or reduced only by the forwarded call; but withdrawAll cannot have been called by non-owner.
        // In the mutant, a subsequent external action (not performed here) could allow a non-owner to withdraw; however, we can detect a violation scenario by checking that owner-only withdrawability still holds: the owner can withdrawAll and reduce balance to 0, but a non-owner must not be able to do so. We assert that a non-owner call to withdrawAll does NOT succeed in reducing address(c).balance.

        // Try to have a non-owner call withdrawAll. In the reference this must fail (revert) due to onlyOwner. In the mutant it will succeed for some inputs.
        bool nonOwnerCouldWithdraw;
        // choose nonOwner (different from owner). Use depositor as candidate non-owner unless depositor == owner (address(this)); ensure it's not owner
        address nonOwner = depositor;
        if (nonOwner == address(this)) {
            // pick another address
            nonOwner = address(0x1234);
            vm.deal(nonOwner, 1 ether);
        }

        // Attempt withdrawAll as non-owner and observe whether it succeeds (i.e., reduces contract balance)
        uint256 balBefore = address(c).balance;
        vm.prank(nonOwner);
        try c.withdrawAll() {
            nonOwnerCouldWithdraw = true;
        } catch {
            nonOwnerCouldWithdraw = false;
        }
        uint256 balAfter = address(c).balance;

        // The single assertion: in the correct contract, a non-owner cannot withdraw: either the call reverts or balance is unchanged.
        // We assert that balance did not decrease due to non-owner withdrawAll (this holds for reference for all inputs); the mutant removes onlyOwner and will allow some inputs to make this false.
        assertTrue(balAfter >= balBefore);
    }
}

// Helper that always reverts on fallback
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
}

// Helper that accepts funds
contract Accepting {
    fallback() external payable {}
}

