import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: attacker address (to act as non-owner) and an amount to send
    function testFuzz_property(address attacker, uint256 depositAmount) public {
        // keep attacker as a non-owner
        vm.assume(attacker != address(this));
        // bound depositAmount to a reasonable range to avoid overflow weirdness
        depositAmount = bound(depositAmount, 1, 1 ether);

        // fund attacker and the contract
        vm.deal(attacker, depositAmount);
        vm.deal(address(c), depositAmount);

        // Deploy a helper that will accept calls (simple recipient)
        Recipient r = new Recipient();

        // Attacker calls sendMoney on c, forwarding some value to recipient r
        vm.prank(attacker);
        // sendMoney will call r with value 0 and empty data (this interaction itself shouldn't change contract balance)
        try c.sendMoney(address(r), 0, "") {
            // ok
        } catch {
            // ignore reverts from sendMoney; reference should handle all admissible inputs
        }

        // Snapshot balance before any withdrawal attempt
        uint256 before = address(c).balance;

        // Now attacker (non-owner) attempts to call withdrawAll()
        vm.prank(attacker);
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for all admissible inputs the reference contract prevents non-owners
        // from reducing its balance via withdrawAll; so if the caller was non-owner, either withdrawAll reverts
        // or the contract balance remains unchanged. We check the observable balance.
        uint256 after = address(c).balance;

        // Assert the invariant: either the call reverted (ok == false) OR the contract balance did not decrease.
        // This reads only c's public surface (address(c).balance) and the revert outcome.
        assertTrue(!ok || after >= before);
    }
}

// Minimal benign recipient used as an external party target for sendMoney
contract Recipient {
    receive() external payable {}
    fallback() external payable {}
}

