        address ownerAddr = c.owner();
        require(ownerAddr == address(this));

        // Call withdrawAll as the owner; on the original contract this will transfer full C balance to this contract
        c.withdrawAll();

        // After withdrawAll, C's balance should be zero. This distinguishes the original (owner can withdraw) from mutant (owner cannot withdraw).
        assert(address(c).balance == 0);
    }

    // Allow the test contract to receive Ether so it can fund deposits and receive withdrawals
    receive() external payable {}
}

