pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: amount to send and whether the callee will revert (as bytes data can trigger behavior);
    // we need an adversarial helper because low-level call to an EOA always succeeds. The helper can optionally revert.
    function testFuzz_property(uint256 sendAmount, bool calleeReverts) public {
        // keep amount reasonable relative to test environment
        sendAmount = bound(sendAmount, 0, 1 ether);

        // Deploy adversarial helper that will either accept or revert depending on the flag
        AttackerHelper helper = new AttackerHelper(calleeReverts);

        // Fund this test contract and ensure c has some balance to forward
        vm.deal(address(this), 1 ether);

        // Send ETH into C via fallback to increase depositsCount and contract balance
        // call as an arbitrary sender (this test contract)
        c.sendMoney{value: 0}(address(0), 0, ""); // noop to ensure call path compiles (no effect)

        // Directly fund c so withdraw could withdraw later
        payable(address(c)).transfer(0);

        // Ensure contract has a nonzero balance to make withdraw meaningful when invoked by owner/non-owner
        // We send 'sendAmount' into c by calling its fallback (send native ETH)
        if (sendAmount > 0) {
            // fund this test contract for sending
            vm.deal(address(this), sendAmount);
            // call c.fallback by sending value
            (bool s, ) = address(c).call{value: sendAmount}("");
            require(s);
        }

        // Record balance before calling sendMoney
        uint256 balBefore = address(c).balance;

        // Now invoke sendMoney to make c call the helper; owner is the deployer (this test contract deployed c in setUp)
        // We must call sendMoney as the owner to match the reference behavior: only owner can call sendMoney in both versions
        // In the reference, onlyOwner requires msg.sender == owner; in the mutant it requires msg.sender != owner.
        // So we call as the owner (this contract). Use prank to set msg.sender
        vm.prank(address(this));
        // The helper will receive up to balBefore (we choose to forward balBefore as value)
        // prepare arbitrary calldata (empty)
        c.sendMoney(address(helper), balBefore, "");

