pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: attacker (caller) and calldata seed (as bytes32) and value
    // General rule: on the reference contract, any non-owner caller's attempt to call sendMoney should revert (fail).
    // The mutant that removes onlyOwner allows some non-owners to call sendMoney successfully; the fuzzer can find one.
    function testFuzz_property(address attacker, uint256 value, bytes32 dataSeed) public {
        // Keep attacker wide but avoid owner (deployer) address; owner is address(this) in setUp
        vm.assume(attacker != address(this));
        // bound value to something reasonable (but allow 0 as well)
        value = bound(value, 0, 1 ether);

        // Prepare calldata bytes derived from dataSeed so fuzzer can vary calldata
        bytes memory data = abi.encodePacked(dataSeed);

        // Fund the contract so sendMoney could potentially transfer funds if called
        vm.deal(address(c), 1 ether);

        // Make the attacker be the msg.sender and attempt the call; capture success via try/catch
        bool ok;
        vm.prank(attacker);
        try c.sendMoney{value: value}(address(attacker), value, data) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert: for the reference C, any non-owner attacker call must fail (ok == false)
        assertTrue(!ok);
    }
}

contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // single test entry
    function runTest(address payable target, uint value, bytes calldata data) public payable {
        // ensure this contract has enough balance to forward
        require(address(this).balance >= value);

        // record initial depositsCount and c balance
        uint beforeDeposits = c.depositsCount();
        uint beforeBal = address(c).balance;

        // perform the call under test: sendMoney will call target.call{value:value}(data)
        // this is the only state-changing call on c in this function
        c.sendMoney(target, value, data);

        // observe after state
        uint afterDeposits = c.depositsCount();
        uint afterBal = address(c).balance;

        // General rule: if c's balance decreased by value then the external call succeeded; otherwise depositsCount increased by at most 1.
        // This compares observed public getters and input 'value'.
        assert((beforeBal - afterBal == value) || (afterDeposits >= beforeDeposits + 1));
    }

    // allow this contract to receive ETH so it can forward
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We take target, value, and data as inputs. The test sends Ether amount `amt` with the call.
    function run(address target, uint amt, bytes calldata dat) public payable {
        require(address(this).balance >= amt, "insufficient balance to forward");
        bool reverted;
        try c.sendMoney{value: amt}(target, amt, dat) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // General rule: if the external call would invoke target's fallback that returns false
        // then sendMoney must revert. We cannot inspect target's internals, so we express
        // the condition by observing that the call to target did NOT transfer Ether from c
        // (i.e., address(c).balance did not decrease by amt) while the test forwarded amt.
        // However, we may only use parameters and the revert flag. So state the rule solely
        // in terms of the call's revert outcome: when the target is a contract address (not EOA)
        // then any failing low-level call must cause sendMoney to revert in the original.
        // We detect contract-ness via code size check on target.
        uint size;
        assembly { size := extcodesize(target) }
        // Assert: if target is a contract, then sendMoney must revert when called with these params
        // that could cause the callee to return false; since we cannot force false here, we assert
        // the general rule that original always reverts for contract targets under failure conditions.
        // Expressed simply: if target has code (is a contract) then reverted must be true.
        assert(!(size > 0) || reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint value, bytes calldata data) public payable {
        require(address(this).balance >= value);
        bool reverted;
        // call sendMoney on the target = address(c) so the call from C will hit C's fallback
        try c.sendMoney(address(c), value, data) { reverted = false; } catch { reverted = true; }
        // On the original contract, calling sendMoney targeting the same contract with any value
        // that makes the fallback execute will always revert; enforce that reverted is true.
        assert(reverted == true);
    }
    receive() external payable { }
}

